"""Desktop smoke test using the package generated by check_path_package.py."""
import sys
from pathlib import Path
from unittest.mock import patch

root_path = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(root_path / 'path_companion'))
from app import App, tk, Image, load_package, reconstruct

folder = sorted((root_path / 'test_artifacts').glob('lineart_paths_*'))[-1]
root = tk.Tk()
root.withdraw()
app = App(root)
app.folder = str(folder)
app.data = load_package(folder)
app.image = Image.open(folder / app.data['files']['flats']).convert('RGBA')
app.applied_settings = dict(threshold=.5, gap=2, tolerance=.6, minimum=0)
app.raw, app.paths, app.joins = reconstruct(folder, app.data, **app.applied_settings)
root.update()
app.fit()
app.selected = ('geometry', 0)
app.hide()
assert ('geometry', 0) in app.hidden
file = folder / 'ui_smoke.svg'
with patch('app.filedialog.asksaveasfilename', return_value=str(file)), \
     patch('app.messagebox.showerror', side_effect=AssertionError):
    app.save()
assert file.is_file()
app.restore()
assert not app.hidden
with patch('app.filedialog.askopenfilename', return_value=str(file.with_suffix('.paths.json'))), \
     patch('app.messagebox.showerror', side_effect=AssertionError):
    app.load_session()
assert ('geometry', 0) in app.hidden
assert app.applied_settings['gap'] == 2
app.close()
print('PASS: preview, local hide/restore, SVG and editable session roundtrip')
